def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Parse moves
    my = [h[0] for h in history]
    op = [h[1] for h in history]
    opp_c = op.count('C')
    opp_d = n - opp_c
    my_d = my.count('D')

    last_my = my[-1]
    last_op = op[-1]

    # Detect opponent behavior windows
    w6 = op[-6:] if n >= 6 else op
    w10 = op[-10:] if n >= 10 else op
    opp_d_6 = w6.count('D')
    opp_d_10 = w10.count('D')

    opp_c_rate = opp_c / n

    # ---------- Phase 1: opening ----------
    if n < 3:
        return 'C'

    # ---------- Aggressive defectors: cut losses ----------
    # If opponent is heavily defecting across recent window, defect.
    if n >= 6 and opp_d_6 >= 5:
        # Rare forgiveness to break deadlock if they seem to waver
        if opp_d_6 == 5 and last_op == 'C' and rng.random() < 0.25:
            return 'C'
        return 'D'

    if n >= 10 and opp_d_10 >= 8:
        return 'D'

    # Overall heavy defector
    if n >= 12 and opp_c_rate < 0.25:
        # Occasional probe to see if they will cooperate
        if opp_d >= 3 and last_op == 'D' and rng.random() < 0.06:
            return 'C'
        return 'D'

    # ---------- Nearly always cooperative opponents ----------
    if opp_d == 0:
        # Pure cooperation pays 3/round vs defection gamble.
        # Only exploit at very end if we trust no retaliation.
        if n >= 97:
            return 'D'
        return 'C'

    # Skim exploitation: opponent rarely retaliates? Check how often they punish our D.
    # Count opponent D's that came immediately after our D (lag-1 retaliation).
    retaliations = 0
    opp_def_after_my_def = 0
    for i in range(1, n):
        if my[i - 1] == 'D':
            opp_def_after_my_def += 1
            if op[i] == 'D':
                retaliations += 1

    # If we've defected enough times and they never retaliate, exploit.
    if opp_def_after_my_def >= 3 and retaliations == 0:
        # Very forgiving/never-retaliating opponent: milk it.
        if n >= 95:
            return 'D'
        # Defect ~ half the time to farm 5 instead of 3 while keeping them cooperating.
        if last_op == 'C' and rng.random() < 0.5:
            return 'D'
        return 'C'

    # ---------- Endgame exploitation ----------
    if n >= 95:
        if opp_c_rate > 0.7 and retaliations <= opp_def_after_my_def * 0.3:
            return 'D'
        if opp_c_rate > 0.55:
            # Last few rounds: defect if they seem unlikely to punish hard
            return 'D'
        return 'D' if opp_c_rate < 0.4 else 'C'

    if n >= 90:
        # Moderately cooperative opponent -> edge toward exploiting at end
        if opp_c_rate > 0.75:
            return 'C'
        if opp_c_rate > 0.5:
            return 'D' if rng.random() < 0.4 else 'C'
        return 'D'

    # ---------- Very cooperative (not pure) ----------
    if opp_c_rate > 0.85:
        # Mostly cooperate, rare probe
        if n > 15 and rng.random() < 0.03 and last_op == 'C':
            return 'D'
        return 'C'

    # ---------- Tit-for-tat core with forgiveness and detection ----------

    # Detect alternating pattern CDCD... which can be exploited
    if n >= 4:
        alt = op[-4:]
        if alt == ['C', 'D', 'C', 'D']:
            # They cooperate on our-favored rounds? Defect when they're about to C.
            # If pattern holds, next opponent move is 'C'.
            if last_op == 'D':
                return 'D'  # next op is C -> we defect, get 5
            return 'C'
        if alt == ['D', 'C', 'D', 'C']:
            if last_op == 'C':
                return 'C'  # next op likely D -> we C, lose; better defect
            return 'D'

    # Genuine tit-for-tat
    if last_op == 'C':
        # Opponent cooperated. Cooperate unless we want to probe.
        if n > 10 and rng.random() < 0.02 and opp_c_rate > 0.6:
            return 'D'
        return 'C'

    # Opponent defected last round: retaliate, but forgive if they seem mostly good.
    if opp_c_rate > 0.6:
        # Forgiving tit-for-tat: forgive with decent probability if defection is isolated
        # Check if this is an isolated defection (surrounded by C's)
        if n >= 3 and op[-2] == 'C' and my[-1] == 'C':
            if rng.random() < 0.35:
                return 'C'
        if rng.random() < 0.2:
            return 'C'
        return 'D'

    if opp_c_rate > 0.4:
        # Mixed opponent: retaliate reliably to avoid being farmed
        # But break DD loops eventually
        if n >= 2 and last_my == 'D' and op[-2] == 'D':
            if rng.random() < 0.15:
                return 'C'
        return 'D'

    # Low cooperation: defect, with rare probes
    if rng.random() < 0.05:
        return 'C'
    return 'D'
